/* Five-module experience. Local state is explicit; no simulated institutional receipt. */
'use strict';
const M=window.YIHU_MODULE_DATA;
const MODULES=[['classroom','book','反诈预警','每日课堂与紧急求助'],['risk','shield','一键维权','问答梳理与材料准备'],['ask','chat','智能问法','常见问题与咨询整理'],['institutions','scale','制度与成果','流程图示、案例与政策'],['guardians','users','多方守护','家人协助与社区服务']];
let riskAnswers={},riskIndex=0,riskDone=false,caseFilter='全部',caseSearch='',faqSearch='',selectedLesson=null;
const RISK_QUESTIONS=[
  {key:'scene',title:'这件事最像哪一种情况？',options:[['call','电话、短信或网上联系'],['invest','投资理财、养老项目'],['shop','购物、合同或服务'],['property','财产被他人占用'],['account','账号、个人信息或线上扣费'],['unknown','说不清楚']]},
  {key:'paid',title:'现在有没有发生钱款损失？',options:[['no','还没有付款'],['yes','已经付款或被扣款'],['unknown','暂时不清楚']]},
  {key:'pressure',title:'对方是否催您立刻付款，或要求保密？',options:[['yes','是，有这样的要求'],['no','没有'],['unknown','不太确定']]},
  {key:'who',title:'对方是什么身份？',options:[['stranger','陌生人或身份尚未核实'],['business','商家、销售或机构人员'],['family','亲友或照护人员'],['unknown','不太清楚']]}
];
function moduleStore(){const raw=readLocal('yihu-modules-v1',{}),v=raw&&typeof raw==='object'?raw:{};return {...v,learned:v.learned&&typeof v.learned==='object'?v.learned:{},evidenceChecks:v.evidenceChecks&&typeof v.evidenceChecks==='object'?v.evidenceChecks:{},guardians:Array.isArray(v.guardians)?v.guardians:[],questions:Array.isArray(v.questions)?v.questions:[],services:Array.isArray(v.services)?v.services:[]};}
function saveModule(data){if(!saveLocal('yihu-modules-v1',data)){toast('本机空间不足，未能保存，请先导出需要的记录。');return false;}return true;}
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function moduleIntro(title,sub){return back()+heading(title,sub);}
function sourceLink(url,label){return /^https:\/\//.test(url||'')?`<a class="reference-link" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';}
function editorialNote(){return '<div class="notice soft">内容供您了解一般信息，具体情况请咨询专业人员。</div>';}
function moduleHub(){return `<section class="module-hub" aria-label="五个服务模块"><div class="section-head"><h2>您需要哪一份帮助？</h2></div><div class="module-grid">${MODULES.map(([id,ic,t,p],i)=>`<button class="module-card" data-go="${id}"><span class="icon-box">${icon(ic)}</span><span><small>0${i+1}</small><strong>${t}</strong><span>${p}</span></span>${icon('chevron')}</button>`).join('')}</div></section>`;}
function emergencyEntry(){return `<button class="emergency-entry" data-go="emergency">${icon('phone')}<span><strong>遇到急事，先找人帮忙</strong><small>联系家人 · 110 拨号 · 保存已有材料</small></span>${icon('chevron')}</button>`;}
function modulesView(){
  const [base,id]=route.split('/');
  const views={family:familyPage,classroom:classroomPage,emergency:emergencyPage,risk:riskPage,evidence:evidencePage,vault:vaultPage,ask:questionPage,institutions:institutionPage,cases:casesPage,policies:policiesPage,guardians:guardiansPage,services:servicesPage,consultations:consultationPage,ticket:ticketPage,volunteer:volunteerPage};
  if(base==='lesson')return lessonPage(id);
  if(base==='faq')return faqPage(id);
  if(base==='case')return casePage(id);
  if(base==='path'){let type='';try{type=id?decodeURIComponent(id):'';}catch{}return pathPage(type);}
  return views[base]?.(id)??null;
}
function todayLesson(){const day=Math.floor(Date.UTC(...localDate().split('-').map((x,i)=>i===1?Number(x)-1:Number(x)))/86400000);return M.lessons[day%M.lessons.length];}
function classroomPage(){const today=todayLesson(),data=moduleStore();return `${moduleIntro('每天学一点防骗知识','从一个小情景开始，学完再做一道小题。')}<section class="feature-panel"><span class="label">${localDate()} · 今日推荐</span><h2>${esc(today.title)}</h2><p>从日常情景中认识风险，学完后可以做一道小测验。</p><button class="primary" data-go="lesson/${today.id}">开始今天的学习 ${icon('arrow')}</button></section><div class="section-head"><h2>课堂目录</h2><span>已学 ${Object.keys(data.learned).filter(id=>M.lessons.some(l=>l.id===id)).length} / ${M.lessons.length}</span></div><div class="module-list">${M.lessons.map(l=>`<button class="module-card" data-go="lesson/${l.id}"><span class="icon-box">${icon(l.icon)}</span><span><strong>${esc(l.title)}</strong><span>${l.topic} · ${data.learned[l.id]?'已完成':'约 2 分钟'}</span></span>${icon('chevron')}</button>`).join('')}</div><div class="section-head"><h2>学习提醒</h2></div><div class="form-panel"><p>可在安卓 App 中主动开启每天上午 9 点的本机提醒。提醒可能受系统省电设置影响，不是实时风险预警。</p><div class="actions"><button class="secondary" data-module="reminder-on">开启每日提醒</button><button class="text-btn" data-module="reminder-off">关闭提醒</button></div><p id="reminder-status" role="status"></p></div>${editorialNote()}`;}
function lessonPage(id){const l=M.lessons.find(x=>x.id===id);if(!l)return back('classroom')+heading('课堂未找到');return `${back('classroom','返回反诈课堂')}${heading(l.title,'跟着情景认识常见风险')}<div class="storyboard">${l.panels.map(([title,text],i)=>`<section class="story-panel"><div class="panel-scene">${icon([l.icon,'clock','shield','users'][i])}<span>第 ${i+1} 幕</span></div><h2>${esc(title)}</h2><p>${esc(text)}</p></section>`).join('')}</div><form class="form-panel" id="quiz-form" data-lesson="${l.id}"><h2>想一想</h2><fieldset class="answer-options"><legend>${esc(l.question)}</legend>${l.choices.map((c,i)=>`<label><input type="radio" name="answer" value="${i}" required><span>${esc(c)}</span></label>`).join('')}</fieldset><button class="primary" type="submit">检查答案</button><p id="quiz-feedback" class="quiz-feedback" role="status"></p></form><p class="source-row">${sourceLink(l.source,l.sourceName)}</p><button class="secondary" data-go="risk">我遇到类似情况，梳理一下</button>`;}
function riskResult(answers=riskAnswers){const map={call:'诈骗疑虑',invest:'投资理财',shop:'消费合同',property:'财产被占',account:'数字权益',unknown:'不太清楚'};const type=map[answers.scene]||'不太清楚';const urgent=answers.pressure==='yes'&&(answers.who==='stranger'||answers.scene==='call');return {type,urgent,reasons:[`您选择的场景：${RISK_QUESTIONS[0].options.find(o=>o[0]===answers.scene)?.[1]||'未填写'}`,answers.paid==='yes'?'您表示已经付款或被扣款。':'付款情况仍需结合具体经过核实。',answers.pressure==='yes'?'您提到被催促付款或被要求保密。':'未提供催促付款或保密的明确信息。']};}
function riskPage(){if(riskDone){const result=riskResult();return `${moduleIntro('先把问题梳理清楚','依据您的选择整理，不是 AI 法律鉴定。')}<section class="feature-panel"><span class="label">建议记录分类 · 您可以更改</span><h2>${result.type}</h2><ul>${result.reasons.map(t=>`<li>${esc(t)}</li>`).join('')}</ul><p>没有风险提示也不代表安全。事实是否构成侵权、应采取什么法律措施，需要进一步核实。</p>${result.urgent?'<div class="notice">出现催促转钱或保密的信号，可以先暂停相关操作并核实，遇到紧急情况优先求助。</div>':''}<div class="actions"><button class="primary" data-module="risk-use">带着分类去记录</button><button class="secondary" data-go="path/${encodeURIComponent(result.type)}">查看求助方向</button></div><button class="text-btn" data-module="risk-reset">重新梳理</button></section>${editorialNote()}`;}
const q=RISK_QUESTIONS[riskIndex];return `${moduleIntro('不知道是哪类问题？','回答四个简单问题，帮您整理记录方向。')}<p class="progress-label">第 ${riskIndex+1} / ${RISK_QUESTIONS.length} 步</p><form class="form-panel" id="risk-form"><h2>${q.title}</h2><fieldset class="answer-options"><legend class="sr-only">${q.title}</legend>${q.options.map(([v,t])=>`<label><input name="risk-answer" type="radio" value="${v}" ${riskAnswers[q.key]===v?'checked':''} required><span>${t}</span></label>`).join('')}</fieldset><div class="actions">${riskIndex?'<button class="secondary" type="button" data-module="risk-back">上一步</button>':''}<button class="primary" type="submit">${riskIndex===3?'查看整理结果':'下一步'}</button></div></form><div class="notice soft">这是透明的问答分类规则，不调用 AI，也不会判断您一定被骗或一定胜诉。</div>`;}
function guardianContacts(){const items=[...moduleStore().guardians];if(prefs.contact&&!items.some(c=>c.phone===prefs.contact.phone))items.unshift({id:'primary',...prefs.contact,relation:'紧急联系人'});return items;}
function emergencyPage(){return `${moduleIntro('紧急求助','先确保自身安全。拨号、发送消息都由您确认。')}<div class="emergency-panel"><h2>需要报警帮助</h2><a class="primary danger-call" href="tel:110">${icon('phone')}打开 110 拨号</a><p>本按钮只打开拨号界面，App 无法确认是否接通或已报警。</p></div><div class="section-head"><h2>联系信任的家人</h2></div><section class="form-panel"><h3>已绑定家庭守护圈？</h3><p>进入守护圈发送求助。家人需打开页面查看，急事请先打电话。</p><button class="primary" data-go="family">进入守护圈求助</button></section>${contactCards(true)}<button class="secondary" data-go="guardians">管理家人联系簿</button><div class="section-head"><h2>把已经有的材料留下来</h2></div><div class="form-panel"><p>可保存当前填写的经过和已选附件副本。只保存您在本 App 中提供的内容，不读取其他 App 的聊天记录，也不能冻结银行账户。</p><button class="primary" data-module="snapshot-draft">保存当前材料快照</button><p id="snapshot-status" role="status"></p><button class="text-btn" data-go="vault">查看已保存快照</button></div>`;}
const EVIDENCE_ITEMS=[['chat','聊天记录','保留已有完整上下文，记下涉及的账号和时间。'],['payment','付款凭证','整理交易时间、金额和流水等已有信息。'],['contract','合同与宣传','保存签署文本、订单及相关宣传材料原件。'],['timeline','事情经过','按顺序记录发生了什么，不清楚的地方标为不确定。'],['original','原始材料','不要覆盖或随意修改原件；附件副本不代替原始载体。']];
function evidencePage(){const data=moduleStore();return `${moduleIntro('一步一步整理材料','先整理您合法持有的材料，具体取证方式向专业人员确认。')}<div class="form-panel"><h2>我的准备清单</h2><p>勾选只表示您已自行整理，不代表材料已经上传或被采信。</p><div class="answer-options">${EVIDENCE_ITEMS.map(([id,t,p])=>`<label><input type="checkbox" data-evidence-check="${id}" ${data.evidenceChecks[id]?'checked':''}><span><strong>${t}</strong><small>${p}</small></span></label>`).join('')}</div><p id="evidence-progress" role="status">已整理 ${Object.values(data.evidenceChecks).filter(Boolean).length} / ${EVIDENCE_ITEMS.length} 项</p><div class="actions"><button class="primary" data-go="report">继续记录并添加附件</button><button class="secondary" data-go="vault">查看材料快照</button></div></div>${editorialNote()}${sourceLink('https://12348.moj.gov.cn/','取证问题可进一步咨询中国法律服务网')}`;}
function pathPage(type){const chosen=C.issueTypes.some(x=>x.id===type)?type:(moduleStore().lastRisk?.type||'不太清楚');const items=chosen==='消费合同'?[['12315','消费投诉举报','整理订单、合同和沟通经过，再了解适用的投诉举报渠道。','12315']]:chosen==='诈骗疑虑'?[['公安机关','疑似诈骗或紧急情况','如发现被骗或遇到紧急危险，可联系公安机关；本 App 不受理报案。','110']]:[['12348','公共法律咨询','先说明情况，了解可能的救济方向和需准备的材料。','12348']];return `${moduleIntro('这件事，可以先找谁？','根据自选场景提供一般渠道信息，受理与程序由相应机构决定。')}<label class="field"><span class="field-label">您记录的问题</span><select id="path-type">${C.issueTypes.map(t=>`<option ${t.id===chosen?'selected':''}>${t.id}</option>`).join('')}</select></label><div class="route-list">${items.map(([t,sub,p,phone])=>`<section class="form-panel"><span class="label">${sub}</span><h2>${t}</h2><p>${p}</p><a class="secondary" href="tel:${phone}">打开 ${phone} 拨号</a></section>`).join('')}<section class="form-panel"><h2>需要进一步判断的路径</h2><p>民事诉讼、法律援助、检察机关支持起诉及公益诉讼有各自条件。不能只靠一个分类直接判断适用。</p><button class="secondary" data-go="institutions">了解参与主体与边界</button></section><section class="form-panel"><h2>咨询前先备好</h2><p>事情经过、发生时间、对方信息、涉及金额和已有材料；不能确定的地方如实说明。</p><div class="actions"><button class="primary" data-go="evidence">打开准备清单</button><button class="secondary" data-go="consultations">整理待咨询问题</button></div></section></div>${editorialNote()}`;}
function questionPage(){return `${moduleIntro('有疑问，先查一查','按问题查找参考卡片，复杂情况整理后再申请人工咨询。')}<form id="faq-search-form" class="question-form"><input name="query" maxlength="150" value="${esc(faqSearch)}" aria-label="查找常见问题" placeholder="例如：钱被骗了、子女代理、诉讼费"><button class="primary" type="submit">查找问答</button></form><div class="mode-label">参考卡片 · 关键词检索</div><div id="faq-results">${faqResults()}</div>${aiPanel()}<section class="form-panel"><span class="label">团队内测</span><h2>没找到适合自己的回答？</h2><p>可以提交脱敏文字，由指定志愿者在工作台接单回复。不承诺即时响应，也不代表律师服务或机构受理。</p><button class="primary" data-go="consultations">申请人工咨询</button></section>`;}
function faqResults(){const query=faqSearch.trim().toLowerCase();const found=M.faqs.filter(f=>!query||[f.question,...f.keywords].some(k=>k.includes(query)||query.includes(k)));return found.length?`<div class="settings">${found.map(f=>`<button class="setting" data-go="faq/${f.id}">${icon('chat')}<span><strong>${esc(f.question)}</strong><small>常见问题</small></span>${icon('chevron')}</button>`).join('')}</div>`:'<div class="empty"><h2>暂未找到相符的参考卡片</h2><p>我们不会为未覆盖的问题编造答案。可换个关键词，或整理后咨询专业人员。</p></div>';}
function faqPage(id){const f=M.faqs.find(x=>x.id===id);if(!f)return back('ask')+heading('问题暂未收录');return `${back('ask','返回问法')}${heading(f.question)}<article class="article-body"><span class="label">参考回答</span><p>${esc(f.answer)}</p><div class="source-row">${sourceLink(f.source,f.sourceName)}</div><p class="field-hint">个案事实、地区和时间可能影响适用，请结合实际进一步确认。</p><button class="primary" data-go="${f.action}">${f.actionLabel}</button></article>`;}
function consultationPage(){const data=moduleStore();return `${moduleIntro('把想问的事情整理好','保存的是本机咨询备忘，不是已发送的咨询工单。')}<form id="consultation-form" class="form-panel"><label class="field"><span class="field-label">我想问什么？</span><textarea name="question" maxlength="1200" minlength="5" required placeholder="简要说明事情和希望了解的问题；请勿填写证件号或银行卡号。"></textarea></label><button class="primary" type="submit">保存待咨询问题</button><p id="consultation-error" class="error" role="alert"></p></form><div class="section-head"><h2>我的咨询备忘</h2></div>${data.questions.length?data.questions.map(q=>`<section class="form-panel"><span class="status">未发送 · 本机备忘</span><p class="preserve-text">${esc(q.text)}</p><small>${stamp(q.createdAt)}</small><div class="actions"><button class="secondary" data-question-export="${q.id}">导出问题</button><button class="text-btn danger" data-question-delete="${q.id}">删除</button></div></section>`).join(''):'<div class="empty"><p>还没有保存的问题。</p></div>'}<a class="secondary" href="tel:12348">打开 12348 拨号</a>`;}
function institutionPage(){return `${moduleIntro('制度与成果','了解各方职责、常见流程和相关资料。')}<div class="module-grid">${[['cases','book','典型案例库','从真实案例中了解常见风险'],['policies','file','法令与政策','带来源和日期的资料目录']].map(([r,ic,t,p])=>`<button class="module-card" data-go="${r}"><span class="icon-box">${icon(ic)}</span><span><strong>${t}</strong><span>${p}</span></span>${icon('chevron')}</button>`).join('')}</div><div class="section-head"><h2>多方参与，各有职责</h2></div><div class="institution-grid">${[['检察机关','依法判断是否属于其职责和案件范围。'],['社会组织与法律服务人员','在自身资格、职责和授权范围内提供协助。'],['老人及家人','说明情况、依法提供线索或材料，决定是否寻求帮助。']].map(([t,p])=>`<section class="form-panel"><h3>${t}</h3><p>${p}</p></section>`).join('')}</div><div class="section-head"><h2>了解求助与协作流程</h2></div><ol class="process-flow">${[['线索整理','描述事实与来源，明确尚待核实的部分。'],['风险评估','由具备职责或专业能力的人员判断紧急程度。'],['分级响应','结合适用条件选择相应求助渠道。'],['反馈与补充','按真实接收方要求补充材料、了解处理情况。']].map(([t,p])=>`<li><strong>${t}</strong><p>${p}</p></li>`).join('')}</ol><div class="notice">上图用于帮助您了解求助步骤。具体受理条件、证据要求和办理程序，以相关机构说明为准；本 App 不代替机构受理或办理。</div><button class="primary" data-go="path">回到实际求助方向</button>`;}
function casesPage(){return `${moduleIntro('典型案例库','了解真实案例，认识常见风险与求助方式。')}<div class="catalog-summary"><strong>${M.cases.length} 条公开参考案例</strong><p>可按类型筛选，也可搜索您关心的问题。</p></div><label class="search-wrap">${icon('search')}<input id="case-search" type="search" value="${esc(caseSearch)}" aria-label="搜索案例" placeholder="搜标题或案例关键词"></label><div class="chips">${['全部','诈骗疑虑','消费合同'].map(t=>`<button class="chip ${caseFilter===t?'active':''}" data-case-filter="${t}">${t}</button>`).join('')}</div><div id="case-results">${caseResults()}</div>`;}
function caseResults(){const found=M.cases.filter(c=>(caseFilter==='全部'||c.type===caseFilter)&&`${c.title} ${c.summary}`.includes(caseSearch.trim()));return found.length?found.map(c=>`<button class="record" data-go="case/${c.id}"><span class="label">${c.type}</span><h2>${c.title}</h2><p>${c.summary}</p><small>${c.publisher} · ${c.date}</small></button>`).join(''):'<div class="empty"><p>此分类下暂未找到相关案例。</p></div>';}
function casePage(id){const c=M.cases.find(x=>x.id===id);if(!c)return back('cases')+heading('案例未找到');return `${back('cases','返回案例库')}${heading(c.title)}<article class="article-body"><span class="label">公开报道摘要</span><h2>事情经过</h2><p>${c.summary}</p><h2>可以留意的信号</h2><p>${c.lesson}</p><p class="field-hint">个案结果不能保证其他案件得到相同处理。</p>${sourceLink(c.source,c.publisher+'原文 · '+c.date)}<div class="actions"><button class="primary" data-go="lesson/${c.linkedLesson}">查看情景课堂</button><button class="secondary" data-go="evidence">整理自己的材料</button></div></article>`;}
function policiesPage(){return `${moduleIntro('法令与政策','保留出处和日期，便于查阅和复核。')}<div class="notice soft">资料目录核验于 ${M.checkedAt}，不自动同步立法动态。草案或报道不等于生效法律，适用前请核对官方现行文本。</div>${M.policies.map(p=>`<article class="form-panel"><span class="label">${p.kind}</span><h2>${p.title}</h2><p>${p.summary}</p><p class="field-hint">${p.dateLabel}：${p.date} · ${p.publisher}</p>${sourceLink(p.url,'打开官方来源')}</article>`).join('')}`;}
function contactCards(emergency=false){const contacts=guardianContacts();return contacts.length?`<div class="module-list">${contacts.map(c=>`<section class="contact-card"><div><h3>${esc(c.name)}</h3><p>${esc(c.relation||'家人')} · ${esc(c.phone)}</p></div><div class="actions"><a class="primary" href="tel:${esc(c.phone.replace(/[^+\d]/g,''))}">${icon('phone')}联系</a>${emergency?`<button class="secondary" data-help-message="${c.id}">准备求助信息</button>`:c.id==='primary'?'<button class="text-btn" data-action="edit-contact">修改</button>':`<button class="text-btn danger" data-guardian-delete="${c.id}">移除</button>`}</div></section>`).join('')}</div>`:'<div class="empty"><h3>先添加一位信任的人</h3><p>保存后可以快速打开拨号界面，暂不自动发送预警。</p></div>';}
function guardiansPage(){return `<section class="form-panel"><h2>家庭守护圈 · 两部手机一起照应</h2><p>邀请一位家人，发送求助并查看联系状态。</p><button class="primary" data-go="family">进入家庭守护圈</button></section>${moduleIntro('家人一起守护','先建立本机联系簿，需要时更容易找到信任的人。')}<div class="notice soft">当前联系人只存本机；添加号码不会邀请对方、授权远程操作或开启实时监控。</div>${contactCards()}<div class="section-head"><h2>添加家人或亲友</h2></div><form class="form-panel" id="guardian-form"><label class="field"><span class="field-label">称呼</span><input name="name" maxlength="30" required></label><label class="field"><span class="field-label">关系</span><select name="relation"><option>子女</option><option>亲友</option><option>照护人员</option><option>其他信任的人</option></select></label><label class="field"><span class="field-label">联系电话</span><input name="phone" type="tel" maxlength="24" required></label><p class="error" id="guardian-error" role="alert"></p><button class="primary" type="submit">保存到联系簿</button></form><section class="form-panel"><h2>同一设备协助填写</h2><p>开启后，维权记录会注明由家人协助。请和长辈一起核对，不代表取得法律代理权限。</p><button class="secondary" data-action="helper">${prefs.helper?'关闭':'开启'}家人协助模式</button></section><button class="secondary" data-go="services">查看社区与公共服务</button>`;}
function servicesPage(){const services=moduleStore().services;return `${moduleIntro('社区与公共服务','官方渠道可直接查阅；本地服务请先独立核实。')}<section class="form-panel"><h2>公共法律服务</h2><p>可通过官方平台了解咨询、法律援助等服务。具体事项以平台和当地机构说明为准。</p><div class="actions"><a class="primary" href="tel:12348">拨打 12348</a>${sourceLink('https://12348.moj.gov.cn/','中国法律服务网')}</div></section><div class="section-head"><h2>我保存的服务信息</h2></div>${services.length?services.map(s=>`<section class="contact-card"><h3>${esc(s.name)}</h3><p>${esc(s.area)} · ${esc(s.hours)}</p><p class="preserve-text">${esc(s.notes)}</p><small>个人保存，未核验为项目合作机构</small><div class="actions"><a class="secondary" href="tel:${esc(s.phone.replace(/[^+\d]/g,''))}">联系 ${esc(s.phone)}</a><button class="text-btn danger" data-service-delete="${s.id}">删除</button></div></section>`).join(''):'<div class="empty"><p>尚未保存服务信息，也没有已接入的合作预约服务。</p></div>'}<form id="service-form" class="form-panel"><h2>记下一处身边的服务</h2><label class="field"><span class="field-label">机构或服务名称</span><input name="name" maxlength="60" required></label><label class="field"><span class="field-label">公开联系电话</span><input name="phone" type="tel" maxlength="24" required></label><label class="field"><span class="field-label">地区或地址</span><input name="area" maxlength="120" required></label><label class="field"><span class="field-label">服务时间</span><input name="hours" maxlength="80" placeholder="不清楚可写待核实" required></label><label class="field"><span class="field-label">服务范围及备注</span><textarea name="notes" maxlength="500"></textarea></label><p id="service-error" class="error" role="alert"></p><button class="primary" type="submit">仅保存到本机</button></form>`;}
